#include "4DPlugin-MDI.h"

#include <string>
#include <vector>
#include <wchar.h>

#pragma mark -

static bool wasMDI;

#if VERSIONWIN

// The one icon handle this plugin created (via LoadImage) and still owns.
// Only touched from the main process (PA_RunInMainProcess), so no locking.
// 4D's own icon is never stored here and therefore never destroyed by us.
static HICON ownedIcon = NULL;

// Copies the 4D application's full path into a std::wstring, with no fixed-size buffer.
// The scan is bounded at 32767 characters (the Windows extended-length path maximum),
// so it never reads past that even if the SDK string were not NUL-terminated.
static bool getApplicationFullPath(std::wstring &out) {
    
    auto us = PA_GetApplicationFullPath();
    const wchar_t *src = (const wchar_t *)us.fString;
    
    if (!src) return false;
    
    out.assign(src, wcsnlen_s(src, 32767));
    
    return !out.empty();
}

#endif

static bool isSDI() {
    
#if VERSIONWIN
    
    PA_Variable args[5];

    args[0] = PA_CreateVariable(eVK_Longint);
    args[1] = PA_CreateVariable(eVK_Longint);
    args[2] = PA_CreateVariable(eVK_Longint);
    args[3] = PA_CreateVariable(eVK_Longint);
    args[4] = PA_CreateVariable(eVK_Longint);
    
    PA_SetLongintVariable(&args[4], (PA_long32)-1);

    PA_ExecuteCommandByID(443 /*GET WINDOW RECT*/, args, 5);

    return (
       (PA_GetLongintVariable(args[0]) == 0)
    && (PA_GetLongintVariable(args[1]) == 0)
    && (PA_GetLongintVariable(args[2]) == 0)
    && (PA_GetLongintVariable(args[3]) == 0));
    
    /* the variable belongs to 4D, no need to PA_ClearVariable (I think) */

#endif
    
    return false;
}

#if VERSIONWIN

static HWND getMDI() {
    
	wasMDI = true;

    PA_ulong32 version = PA_Get4DVersion();
    
    if (version >= 16)
        return (HWND)PA_GetMainWindowHWND();

    // Altura MAc2Win does not allow multiple instances of the same app
    // we can assume that the window class is the folder name of the application
    
    HWND mdi = NULL;
    std::wstring path;
    
    if (!getApplicationFullPath(path))
        return NULL;
    
    //remove file name (4D.exe)
    size_t sep = path.find_last_of(L"\\/");
    if (sep == std::wstring::npos)
        return NULL;
    path.erase(sep);
    //check instance as well, to be sure
    HINSTANCE h = (HINSTANCE)PA_Get4DHInstance();
    
    do {
        mdi = FindWindowExW(NULL, mdi, path.c_str(), NULL);
        if (mdi)
        {
            if (h == (HINSTANCE)GetWindowLongPtr(mdi, GWLP_HINSTANCE))
            {
                break;
            }
        }
    } while (mdi);
    
   return mdi;
}

#endif

#if VERSIONWIN

void OnExit() {
            
        HWND mdi = getMDI();
        
        if (mdi) {

			EnableMenuItem(GetSystemMenu(mdi, FALSE),
				SC_CLOSE,
				MF_BYCOMMAND | MF_ENABLED);
            
            DWORD_PTR ptr = 0;
            HICON hIcon = NULL;
            
            std::wstring applicationPath;
            
            if (getApplicationFullPath(applicationPath))
            {
                hIcon = ExtractIconW((HINSTANCE)PA_Get4DHInstance(),
                                     applicationPath.c_str(), 0);
                
                //ExtractIcon returns 1 (not NULL) when the file is not an executable/icon file
                if ((UINT_PTR)hIcon <= 1)
                    hIcon = NULL;
                
                if (!hIcon)
                {
                    SHFILEINFOW fileinfo = {};
                    if (SHGetFileInfoW(applicationPath.c_str(),
                                       0,
                                       &fileinfo,
                                       sizeof(fileinfo),
                                       SHGFI_LARGEICON | SHGFI_ICON))
                    {
                        hIcon = fileinfo.hIcon;
                    }
                }
            }
            
            if (hIcon)
            {
                if (SendMessageTimeoutW(mdi,
                                        WM_SETICON,
                                        ICON_SMALL,
                                        (LPARAM)hIcon,
                                        SMTO_NORMAL,
                                        MESSAGE_TIMEOUT_MS,
                                        &ptr))
                {
                    //release the icon we loaded via MDI USE ICON FILE, if it was the one replaced
                    if (ownedIcon && ((HICON)ptr == ownedIcon))
                    {
                        DestroyIcon(ownedIcon);
                        ownedIcon = NULL;
                    }
                }
            }
            
            
        }

}

#endif

void PluginMain(PA_long32 selector, PA_PluginParameters params) {
        
    try
    {
        switch(selector)
        {
            case kDeinitPlugin:
#if VERSIONWIN
				//too late to call isSDI() which depends on PA_ExecuteCommandByID
				if (wasMDI) {
					PA_RunInMainProcess((PA_RunInMainProcessProcPtr)OnExit, NULL);
				}
#endif
                break;
                
                // --- MDI
                
            case 1 :
                if(!isSDI()) {
                    PA_RunInMainProcess((PA_RunInMainProcessProcPtr)MDI_Get_title, params);
                }
                break;
            case 2 :
                if(!isSDI()) {
                    PA_RunInMainProcess((PA_RunInMainProcessProcPtr)MDI_SET_TITLE, params);
                }
                break;
            case 3 :
                if(!isSDI()) {
                    PA_RunInMainProcess((PA_RunInMainProcessProcPtr)MDI_USE_ICON_FILE, params);
                }
                break;
            case 4 :
                if(!isSDI()) {
                    PA_RunInMainProcess((PA_RunInMainProcessProcPtr)MDI_MAXIMIZE, params);
                }
                break;
            case 5 :
                if(!isSDI()) {
                    PA_RunInMainProcess((PA_RunInMainProcessProcPtr)MDI_MINIMIZE, params);
                }
                break;
            case 6 :
                if(!isSDI()) {
                    PA_RunInMainProcess((PA_RunInMainProcessProcPtr)MDI_SET_CLOSE_BOX_ENABLED, params);
                }
                break;
            case 7 :
                if(!isSDI()) {
                    PA_RunInMainProcess((PA_RunInMainProcessProcPtr)MDI_Get_close_box_enabled, params);
                }
                break;
            case 8 :
                if(!isSDI()) {
                    PA_RunInMainProcess((PA_RunInMainProcessProcPtr)MDI_RESTORE, params);
                }
                break;
            case 9 :
                if(!isSDI()) {
                    PA_RunInMainProcess((PA_RunInMainProcessProcPtr)MDI_SET_POSITION, params);
                }
                break;
            case 10 :
                if(!isSDI()) {
                    PA_RunInMainProcess((PA_RunInMainProcessProcPtr)MDI_GET_POSITION, params);
                }
                break;
                
        }
        
    }
    catch(...)
    {
        
    }
    
}

#pragma mark -

void MDI_Get_title(PA_PluginParameters params) {

    sLONG_PTR *pResult = (sLONG_PTR *)params->fResult;
    
    C_TEXT returnValue;
    
#if VERSIONWIN

    HWND mdi = getMDI();
    
    if (mdi) {
        int length = GetWindowTextLengthW(mdi);
        
        if (length > 0) {
            std::vector<wchar_t> buf((size_t)length + 1);
            int copied = GetWindowTextW(mdi, &buf[0], (int)buf.size());
            if (copied < 0) copied = 0;
            
            returnValue.setUTF16String((const PA_Unichar *)&buf[0], (PA_long32)copied);
        }
        
    }

#endif

    returnValue.setReturn(pResult);
}

void MDI_SET_TITLE(PA_PluginParameters params) {

    #if VERSIONWIN
            
    HWND mdi = getMDI();
    
    if (mdi) {
        
        C_TEXT Param1;
        
        PackagePtr pParams = (PackagePtr)params->fParameters;
        Param1.fromParamAtIndex(pParams, 1);
        
        SetWindowTextW(mdi, (LPCWSTR)Param1.getUTF16StringPtr());
        
    }
    
    #endif
}

void MDI_USE_ICON_FILE(PA_PluginParameters params) {

    #if VERSIONWIN
            
    HWND mdi = getMDI();
    
    if (mdi) {
        
        DWORD_PTR ptr;
        
        PackagePtr pParams = (PackagePtr)params->fParameters;
        
        C_TEXT Param1;
        
        Param1.fromParamAtIndex(pParams, 1);
        
        
        //ICON_SMALL expects the small-icon metrics, not the default (large) icon size
        HICON hIcon = (HICON)LoadImageW(NULL,
                                        (LPCWSTR)Param1.getUTF16StringPtr(),
                                        IMAGE_ICON,
                                        GetSystemMetrics(SM_CXSMICON),
                                        GetSystemMetrics(SM_CYSMICON),
                                        LR_LOADFROMFILE);
        if(hIcon)
        {
            ptr = 0;
            
            if (SendMessageTimeoutW(mdi,
                                    WM_SETICON,
                                    ICON_SMALL,
                                    (LPARAM)hIcon,
                                    SMTO_NORMAL,
                                    MESSAGE_TIMEOUT_MS,
                                    &ptr))
            {
                //WM_SETICON returns the previous icon. Destroy it only if we created it;
                //4D's own icon (or one set by anything else) is not ours to destroy.
                if (ownedIcon && ((HICON)ptr == ownedIcon))
                {
                    DestroyIcon(ownedIcon);
                }
                ownedIcon = hIcon;
            }
            //on failure/timeout the message may still be delivered later, so the handle
            //is deliberately not destroyed here (a small leak is safer than a dangling icon).
        }
        
    }
    
    #endif
}

