void MDI_SET_POSITION(PA_PluginParameters params) {
        
    #if VERSIONWIN
    
    HWND mdi = getMDI();
    
    if (mdi) {
        
        PackagePtr pParams = (PackagePtr)params->fParameters;
        
        C_LONGINT insertAfter;
        C_LONGINT x;
        C_LONGINT y;
        C_LONGINT w;
        C_LONGINT h;
        C_LONGINT flags;
        
        insertAfter.fromParamAtIndex(pParams, 1);
        x.fromParamAtIndex(pParams, 2);
        y.fromParamAtIndex(pParams, 3);
        w.fromParamAtIndex(pParams, 4);
        h.fromParamAtIndex(pParams, 5);
        flags.fromParamAtIndex(pParams, 6);
        
        HWND hWndInsertAfter = (HWND)insertAfter.getIntValue();
        
        if((hWndInsertAfter != HWND_BOTTOM)
           && (hWndInsertAfter != HWND_NOTOPMOST)
           && (hWndInsertAfter != HWND_TOP)
           && (hWndInsertAfter != HWND_TOPMOST)){
            //remember, since v1264bits/v14, 4D windowRef is not HWND
            hWndInsertAfter = (HWND)PA_GetHWND((PA_WindowRef)hWndInsertAfter);
            
            //an unknown 4D window reference yields NULL, which SetWindowPos would
            //read as HWND_TOP: do nothing instead of silently doing something else
            if (!hWndInsertAfter || !IsWindow(hWndInsertAfter)) {
                return;
            }
        }
        
        if (!SetWindowPos(mdi,
                          hWndInsertAfter,
                          x.getIntValue(),
                          y.getIntValue(),
                          w.getIntValue(),
                          h.getIntValue(),
                          flags.getIntValue())) {
            //the command has no error channel to 4D; leave a trace for DebugView
            wchar_t msg[96];
            wsprintfW(msg, L"MDI SET POSITION: SetWindowPos failed (error %lu)\n", GetLastError());
            OutputDebugStringW(msg);
        }
        
    }
    
    #endif
}

void MDI_GET_POSITION(PA_PluginParameters params) {

    PackagePtr pParams = (PackagePtr)params->fParameters;
    
    C_LONGINT Param1;
    C_LONGINT Param2;
    C_LONGINT Param3;
    C_LONGINT Param4;
    
    #if VERSIONWIN
            
    HWND mdi = getMDI();
    
    if (mdi) {
        
        RECT rect;
        
        if(GetWindowRect(mdi, &rect))
        {
            Param1.setIntValue(rect.left);
            Param2.setIntValue(rect.top);
            Param3.setIntValue(rect.right - rect.left);
            Param4.setIntValue(rect.bottom - rect.top);
        }
        
    }

    #endif
    
    Param1.toParamAtIndex(pParams, 1);
    Param2.toParamAtIndex(pParams, 2);
    Param3.toParamAtIndex(pParams, 3);
    Param4.toParamAtIndex(pParams, 4);
}
